const ICONS={file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h5',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',chat:'M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z',branch:'M6 3v12 M6 15a3 3 0 1 0 0 6 3 3 0 0 0 0-6 M18 3a3 3 0 1 0 0 6 3 3 0 0 0 0-6 M6 9a12 12 0 0 0 12 0',help:'M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3 M12 17h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',shield:'M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11 M9 12l2 2 4-4',save:'M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h12l4 4v12a2 2 0 0 1-2 2z M17 21v-8H7v8 M7 3v5h8',spark:'M12 3l2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6z M21 2v4 M19 4h4',info:'M12 16v-4 M12 8h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',upload:'M12 16V3 M7 8l5-5 5 5 M20 16v4a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1v-4',arrow:'M5 12h14 M12 5l7 7-7 7',check:'M20 6L9 17l-5-5',send:'M22 2L9 15 M22 2l-7 20-6-7-7-6z',edit:'M12 20h9 M16.5 3.5a2.12 2.12 0 0 1 3 3L9 17l-4 1 1-4z',clock:'M12 8v4l3 3 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',copy:'M9 9h12v12H9z M5 15H3V3h12v2'};
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[name]||ICONS.file}"/></svg>`;
const esc=(value)=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=selector=>document.querySelector(selector);
const clone=value=>JSON.parse(JSON.stringify(value));
let serial=0;
const uid=prefix=>`${prefix}-${Date.now().toString(36)}-${++serial}`;
const SAMPLE=`[2026-10-08 10:05] 我：这周排期已经满了，新增需求需要调整优先级。
[2026-10-08 10:07] 林予：明白。你给我两个方案，以及各自会影响哪些已排期任务，我来确认。
[2026-10-08 10:12] 我：可以延后报表，也可以把新增需求拆成两期。
[2026-10-08 10:14] 林予：先告诉我第一期能覆盖什么。没有评估清楚之前，不要先承诺日期。
[2026-10-09 15:20] 我：客户希望提前做完。
[2026-10-09 15:22] 林予：我们先明确取舍，别只说做不了。需要我决定的部分，列出来就行。
[2026-10-09 16:00] 陈澈：如果要调整，我可以一起拆任务。先把当前卡点对齐？
[2026-10-09 16:05] 我：主要是测试时间不足。
[2026-10-09 16:07] 陈澈：那我们把依赖列一下。别急着给时间，先看哪些能并行。`;
const steps=[['file','导入聊天','上传记录即可开始'],['people','对象画像','自动建立 · 按需查看'],['chat','聊天预演','把对话先聊一遍'],['branch','分支与复盘','比较不同表达路径']];
const titles=[['01 / 建立对话的依据','从你们的对话开始。','放入聊天记录或其他材料，让特定对象的表达方式有迹可循。'],['02 / 从材料理解特定对象','认识这一次的对话对象。','人格由聊天记录自动建立，无需填写；这里仅展示来源与已知信息。'],['03 / 让不同表达有机会发生','把这次对话，先聊一遍。','导入后即可与模拟对象试聊，探索回应，再尝试另一种说法。'],['04 / 留下选择，而不是一个答案','两条路径，一次更好的选择。','在相同人格和背景下比较表达，观察差异，保留自己的立场。']];
let state={stage:0,material:SAMPLE,materialName:'协作对话示例.txt',sample:true,materialVersion:1,personas:[],selected:null,branches:[],activeBranch:null,compareA:null,compareB:null,context:{background:'当前排期已满，新增需求需要明确取舍。',goal:'说明资源限制，并推动优先级协商',boundary:'不承诺额外产能，不编造交付日期。'},draft:'这个需求我们排不进去，你们重评优先级吧。'};
let busy=false,toastTimer,pendingTimer;
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function records(text){return text.split(/\r?\n/).map((line,index)=>{const cleaned=line.replace(/^\s*\[[^\]]+\]\s*/,'').trim();const match=cleaned.match(/^([^：:\n]{1,24})[：:]\s*(.+)$/);return match?{id:`source-${index+1}`,speaker:match[1].trim(),text:match[2].trim(),line:index+1}:null;}).filter(Boolean);}
function candidates(){return [...new Set(records(state.material).map(r=>r.speaker))].filter(name=>!['我','本人','自己','self','SELF','user'].includes(name)).slice(0,12);}
function currentPersona(){return state.personas.find(p=>p.id===state.selected)||state.personas[0];}
function currentBranch(){return state.branches.find(b=>b.id===state.activeBranch);}
function navigation(){document.getElementById('navigation').innerHTML=steps.map((s,i)=>`<button class="nav-item ${state.stage===i?'active':''}" data-stage="${i}" ${state.stage===i?'aria-current="step"':''}>${icon(s[0])}<span>${s[1]}</span><span class="nav-number">0${i+1}</span></button>`).join('');$('#workflow').innerHTML=steps.map((s,i)=>`<button class="step ${state.stage===i?'current':''}" data-stage="${i}"><span class="step-number">${i<state.stage?'✓':i+1}</span><span><strong>${s[1]}</strong><small>${s[2]}</small></span></button>`).join('');const t=titles[state.stage];$('#pageEyebrow').textContent=t[0];$('#pageTitle').textContent=t[1];$('#pageDescription').textContent=t[2];$('#sideStatus').textContent=state.personas.length?'对象已自动建立':'等待导入聊天';}
function setStage(stage){if(busy)return notify('正在生成演示回复，请稍候。');state.stage=stage;render();window.scrollTo({top:0,behavior:'smooth'});}
function emptyView(title,description,button,stage){return `<div class="panel empty-state"><div class="person-avatar">${icon('people')}</div><h2>${title}</h2><p>${description}</p><button class="button primary" data-stage="${stage}">${button} ${icon('arrow')}</button></div>`;}
function materialView(){const names=candidates(),count=records(state.material).length;return `<div class="content-grid"><section class="panel"><div class="panel-head"><div class="head-label">${icon('file')}<div><h3>对话材料</h3><small>一段真实的交流，比一个笼统的标签更有用。</small></div></div><span class="tag">${state.sample?'虚构示例':'用户输入'}</span></div><div class="panel-body"><div class="upload-zone"><span class="upload-icon">${icon('upload')}</span><h3>放入你想了解的那个人的材料</h3><p>支持 TXT、MD、JSON · 最大 2 MB · 也可以直接粘贴</p><button class="button small" id="importButton">${icon('upload')}选择本地文件</button><input id="fileInput" type="file" accept=".txt,.md,.json,text/plain,application/json" hidden></div><div class="material-label"><label for="materialText">或者，直接粘贴内容</label><span>建议格式：姓名：消息内容</span></div><textarea id="materialText" placeholder="林予：先把两个方案和影响列出来。\n我：好，我先整理取舍。">${esc(state.material)}</textarea><div class="hint-box"><strong>保留上下文，也保留说话人。</strong><br>导入后自动识别对象并进入预演，不需要填写人格。请使用带说话人标记的聊天记录。</div></div><div class="panel-foot"><span class="subtle">材料只在当前页面中使用；点击保存才写入本地项目。</span><button class="button primary" id="generatePersonas">导入并开始预演 ${icon('arrow')}</button></div></section><aside class="panel"><div class="panel-head"><div><h3>材料概览</h3><small>确认我们正在看谁的对话。</small></div><span class="tag green">${state.material.trim()?'已载入':'待输入'}</span></div><div class="panel-body"><div class="source-line"><span class="source-icon">${icon('file')}</span><div class="source-info"><strong id="materialName">${esc(state.materialName)}</strong><small>UTF-8 文本 · <span id="materialLength">${state.material.length}</span> 个字符</small></div></div><div class="metric-row"><div class="metric"><strong id="recordCount">${count}</strong><small>识别的消息</small></div><div class="metric"><strong id="personCount">${names.length}</strong><small>候选对象</small></div><div class="metric"><strong>v${state.materialVersion}</strong><small>材料版本</small></div></div><div class="section-label"><span>自动识别的对象</span></div><div id="candidateList">${candidateHTML(names)}</div><div class="separator"></div><div class="empty-illustration"><span class="illustration-node">${icon('file')}</span><span class="illustration-line"></span><span class="illustration-node">${icon('people')}</span><span class="illustration-line"></span><span class="illustration-node">${icon('chat')}</span></div><p class="mini-note">材料 → 人格 → 对话<br>人格不是标签，而是有依据的沟通模型。</p></div></aside></div>`;}
function candidateHTML(names){return names.length?names.slice(0,5).map((name,i)=>`<div class="person-mini"><span class="person-avatar ${i%2?'alt':''}">${esc(name.slice(-1))}</span><div><strong>${esc(name)}</strong><p>${state.sample?(name==='林予'?'项目负责人 · 虚构对象':'协作同事 · 虚构对象'):'从说话人格式中提取 · 身份待核对'}</p></div><span class="tag">自动建模</span></div>`).join(''):'<p class="subtle">暂未识别对象。聊天记录需包含说话人，例如“姓名：消息内容”。</p>';}
function generatePersonas(){
  if(!state.material.trim())return notify('请先导入或粘贴聊天记录。');
  const parsed=records(state.material),names=candidates();
  if(!names.length){state.stage=0;render();return notify('无法识别聊天对象。请导入带“姓名：内容”的聊天记录或支持的消息 JSON；无需填写人格。');}
  state.personas=names.map(name=>{
    const all=parsed.filter(r=>r.speaker===name),evidence=all.slice(0,3);
    const special=state.sample&&name==='林予',other=state.sample&&name==='陈澈';
    const avg=Math.round(all.reduce((sum,r)=>sum+r.text.length,0)/all.length);
    const asks=all.filter(r=>/[?？]/.test(r.text)).length;
    const p={id:uid('persona'),name,role:special?'项目负责人':other?'协作同事':'聊天记录中的对象',
      style:special?'表达直接、简洁；偏好先明确选项与影响，再作决定。':other?'常用协作式提问，倾向先对齐卡点、拆解依赖。':`已识别 ${all.length} 条发言，平均 ${avg} 字；其中 ${asks} 条带问号。更深入的表达风格待模型接入后分析。`,
      concerns:special?'任务优先级、方案取舍、承诺是否经过评估。':other?'协作方式、任务依赖、可并行的环节。':'尚未进行语义分析，不推断偏好。',
      boundary:special?'未评估前不承诺日期；需要明确哪些事项由自己决定。':other?'排期未评估前不急于给时间。':'材料未经过语义分析，不推断边界。',
      unknown:'这些材料不等于完整人格，不能据此确定真实对象当下的情绪或反应。',evidence,version:1,materialVersion:state.materialVersion,demo:special||other};
    p.confirmed=clone({...p,confirmed:null});return p;
  });
  const primary=state.personas.reduce((best,p)=>parsed.filter(r=>r.speaker===p.name).length>parsed.filter(r=>r.speaker===best.name).length?p:best,state.personas[0]);
  state.selected=primary.id;createBranch(primary.confirmed);state.stage=2;render();
  notify(state.sample?'示例对象已自动建立，直接输入消息即可预演。':'已按说话人自动建立演示对象；无需填写人格。深度人格分析尚未接入 AI。');
}
function personaView(){
  const p=currentPersona();
  if(!p)return emptyView('导入记录，就能建立对话对象。','无需手填人格。系统自动识别对象，建立可追溯的画像。','导入聊天记录',0);
  return `<div class="persona-layout"><aside class="persona-list">${state.personas.map((person,i)=>`<button class="persona-choice ${person.id===p.id?'active':''}" data-persona="${person.id}"><span class="person-avatar ${i%2?'alt':''}">${esc(person.name.slice(-1))}</span><span><strong>${esc(person.name)}</strong><small>自动建立 · v${person.version}</small></span></button>`).join('')}<div class="hint-box"><strong>不用自己捏人格。</strong><br>所有画像来自导入记录。本页只供查看，不需要填写或确认。</div></aside><section class="panel"><div class="panel-head"><div class="head-label">${icon('people')}<div><h3>对象画像 · ${esc(p.name)}</h3><small>来源：${esc(state.materialName)} / 材料 v${p.materialVersion}</small></div></div><span class="tag green">自动建立</span></div><div class="panel-body"><div class="persona-summary"><span class="person-avatar">${esc(p.name.slice(-1))}</span><div><h2>${esc(p.name)}</h2><span class="subtle">${esc(p.role)} · ${p.demo?'虚构示例画像':'自动统计 / 未接入深度模型'}</span></div></div><div class="auto-profile"><article><span class="eyebrow">表达方式</span><p>${esc(p.style)}</p></article><article><span class="eyebrow">关注点</span><p>${esc(p.concerns)}</p></article><article><span class="eyebrow">信息边界</span><p>${esc(p.boundary)}</p></article></div><details class="profile-evidence"><summary>查看建模依据 · ${p.evidence.length} 个来源片段</summary>${p.evidence.map(e=>`<div class="evidence"><small>${esc(e.id)} / 第 ${e.line} 行 / ${esc(e.speaker)}</small><blockquote>“${esc(e.text)}”</blockquote></div>`).join('')}</details><p class="subtle" style="margin-top:20px">${esc(p.unknown)}</p></div><div class="panel-foot"><button class="button text" data-stage="0">${icon('upload')}更新聊天记录</button><button class="button primary" id="startPersona">与 ${esc(p.name)} 预演 ${icon('arrow')}</button></div></section></div>`;
}
function startPersona(){const p=currentPersona();if(!p||busy)return;const existing=state.branches.find(b=>b.persona.id===p.id&&b.persona.version===p.version);if(existing)state.activeBranch=existing.id;else createBranch(p.confirmed||clone({...p,confirmed:null}));state.stage=2;render();}
function createBranch(persona,prefix=[],parent=null,forkAt=null,context=state.context){const b={id:uid('branch'),name:`路径 ${String.fromCharCode(65+state.branches.length%26)}${state.branches.length>=26?Math.floor(state.branches.length/26):''}`,persona:clone(persona),messages:clone(prefix),parent,forkAt,context:clone(context),createdAt:new Date().toISOString()};state.branches.push(b);state.activeBranch=b.id;if(!state.compareA)state.compareA=b.id;if(state.branches.length>1)state.compareB=b.id;return b;}
function chatView(){const b=currentBranch();if(!b)return emptyView('导入聊天记录，直接开始预演。','系统从记录建立特定对象，无需填写人格。','导入聊天记录',0);const p=b.persona;return `<div class="chat-layout"><section class="panel wechat-chat" aria-label="聊天预演窗口"><div class="panel-head chat-heading"><div class="person-mini" style="padding:0"><span class="person-avatar">${esc(p.name.slice(-1))}</span><div><strong>${esc(p.name)}</strong><p><i class="chat-status-dot"></i>聊天预演 · 人格 v${p.version}</p></div></div><span class="tag amber">规则演示回复</span></div><div class="auto-chat-toolbar"><label for="chatPersona">预演对象</label><select id="chatPersona">${state.personas.map(person=>`<option value="${person.id}" ${person.id===p.id?'selected':''}>${esc(person.name)}</option>`).join('')}</select><button class="button text small" data-stage="1">查看自动画像 ${icon('arrow')}</button></div><div class="branch-tabs" aria-label="对话分支">${state.branches.map(branch=>`<button class="branch-tab ${branch.id===b.id?'active':''}" data-branch="${branch.id}">${icon('branch')} ${esc(branch.name)} · ${esc(branch.persona.name)}</button>`).join('')}</div><div class="chat-feed" id="chatFeed" role="log" aria-label="预演消息" aria-live="polite">${b.messages.length?chatHistoryHTML(b.messages):`<div class="chat-start"><span class="person-avatar">${icon('chat')}</span><h3>先在这里，试着聊一遍。</h3><p>在下方输入你准备说的话。<br>对话仅用于预演，不会发送给真实对象。</p></div>`}${busy?`<article class="message typing-message"><span class="person-avatar" aria-hidden="true">${esc(p.name.slice(-1))}</span><div class="message-content"><div class="message-name">${esc(p.name)}</div><div class="bubble typing-bubble" role="status" aria-label="正在生成演示回复"><i></i><i></i><i></i></div></div></article>`:''}</div><div class="composer"><div class="composer-toolbar"><label for="chatDraft">${icon('edit')} 写一条消息</label><span>输入时实时检查措辞</span></div><textarea id="chatDraft" rows="3" aria-describedby="chatInputHelp" placeholder="输入消息…" ${busy?'disabled':''}>${esc(state.draft)}</textarea><div class="composer-bottom"><span class="subtle" id="chatInputHelp">Enter 发送 · Shift + Enter 换行</span><button class="button primary" id="sendMessage" ${busy?'disabled':''}>发送并预演 ${icon('send')}</button></div></div></section><aside class="panel"><div class="panel-head"><div><h3>本次预演背景（可选）</h3><small>无需填写；有特殊背景时再补充。</small></div>${icon('people')}</div><div class="panel-body"><div class="snapshot"><strong>当前人格快照 · v${p.version}</strong><br>${esc(p.style)}<br><span class="subtle">来源材料 v${p.materialVersion}；演示回复尚未验证人格还原度。</span></div><div class="context-fields" style="margin-top:20px">${contextField('background','当前背景',b.context.background,true,b.messages.length>0)}${contextField('goal','你想达成什么',b.context.goal,false,b.messages.length>0)}${contextField('boundary','必须保留的边界',b.context.boundary,true,b.messages.length>0)}</div><div class="hint-box"><strong>对话中的知识范围</strong><br>正式版本将隔离用户私下目标。此处只演示流程，不调用模型。首条消息发送后背景锁定；改变背景请新建预演。</div></div><div class="panel-foot"><button class="button small" id="newSession">新建预演</button><button class="button soft small" data-stage="3">比较分支 ${icon('arrow')}</button></div></aside></div>`;}
function contextField(key,label,value,multiline,locked){return `<div><label for="context-${key}">${label}${locked?' · 已锁定':''}</label>${multiline?`<textarea id="context-${key}" data-context="${key}" ${locked?'readonly':''}>${esc(value)}</textarea>`:`<input id="context-${key}" data-context="${key}" value="${esc(value)}" ${locked?'readonly':''}>`}</div>`;}
function chatHistoryHTML(messages){return messages.map((m,index)=>{const date=new Date(m.createdAt),previous=index?new Date(messages[index-1].createdAt):null;const showTime=Number.isFinite(date.getTime())&&(!previous||!Number.isFinite(previous.getTime())||date-previous>=5*60*1000);const label=showTime?date.toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}):'';return `${showTime?`<div class="chat-time"><time datetime="${esc(date.toISOString())}">${esc(label)}</time></div>`:''}${messageHTML(m)}`;}).join('');}
function messageHTML(m){const b=currentBranch(),user=m.role==='user';return `<article class="message ${user?'user':''}" aria-label="${user?'你':esc(b.persona.name)}的消息"><span class="person-avatar" aria-hidden="true">${user?'你':esc(b.persona.name.slice(-1))}</span><div class="message-content"><div class="message-name">${user?'你':esc(b.persona.name)}</div><div class="bubble">${esc(m.text)}</div>${user?`<div class="message-tools"><button class="button text" data-fork="${m.id}" ${busy?'disabled':''}>${icon('branch')}从这里分叉</button></div>`:''}</div></article>`;}

function mockReply(text,persona,turn){const teammate=persona.name==='陈澈';if(/排不进|做不了|不行|你们.*吧/.test(text))return teammate?'我们先对齐卡点吧。你说的排不进去，是测试时间不够，还是有其他依赖？':'你指的是不能直接加进来，还是需要调整已有任务？请把要取舍的选项说明一下。';if(/确认|优先|调整|取舍|方案/.test(text))return teammate?'可以，我们先把依赖和影响列出来，再看哪些能并行。具体时间等评估后再确认。':'我理解需要先做取舍。请列出需要调整的任务及影响，再确认下一步；先不用承诺日期。';if(/谢谢|好的|明白/.test(text))return '好，我们按刚才明确的下一步继续，未确认的信息先保留。';return `${turn>1?'关于你刚才补充的内容，':'我看到了你的表达。'}你希望我具体确认什么？请补充希望达成的下一步。`}
function sendMessage(){if(busy)return;const b=currentBranch();if(!b)return notify('请先导入聊天记录。');const text=state.draft.trim();if(!text)return notify('先输入一条准备说的话。');if(text.length>5000)return notify('这份原型每条消息最多 5000 个字符。');b.messages.push({id:uid('msg'),role:'user',text,createdAt:new Date().toISOString()});state.draft='';busy=true;render();scrollChat();pendingTimer=setTimeout(()=>{b.messages.push({id:uid('msg'),role:'assistant',text:mockReply(text,b.persona,b.messages.filter(m=>m.role==='user').length),createdAt:new Date().toISOString(),mode:'scripted-demo'});busy=false;render();scrollChat();$('#chatDraft')?.focus({preventScroll:true});},600);}
function scrollChat(){requestAnimationFrame(()=>{const feed=$('#chatFeed');if(feed)feed.scrollTop=feed.scrollHeight;});}
function forkMessage(id){if(busy)return;const b=currentBranch(),index=b.messages.findIndex(m=>m.id===id&&m.role==='user');if(index<0)return;const original=b.messages[index];createBranch(b.persona,b.messages.slice(0,index),b.id,id,b.context);state.draft=original.text;render();notify('新路径保留分叉点之前的对话。修改这条消息，再发送。');$('#chatDraft').focus();}
function branchOptions(selected){return state.branches.map(b=>`<option value="${b.id}" ${b.id===selected?'selected':''}>${esc(b.name)} · ${esc(b.persona.name)} / v${b.persona.version}</option>`).join('');}
function comparePanel(b){return `<section class="panel"><div class="panel-head"><div><h3>${esc(b.name)}</h3><small>${esc(b.persona.name)} · 人格 v${b.persona.version} · ${b.messages.filter(m=>m.role==='user').length} 轮对话</small></div><span class="tag">${b.parent?'分叉路径':'初始路径'}</span></div><div class="compare-feed">${b.messages.length?b.messages.map(m=>`<div class="compare-message ${m.role==='user'?'user':''}"><small>${m.role==='user'?'你':esc(b.persona.name)+' · 演示回复'}</small>${esc(m.text)}</div>`).join(''):'<p class="subtle">这条路径还没有消息。</p>'}</div></section>`;}
function latestUser(b){return [...b.messages].reverse().find(m=>m.role==='user');}
function compareView(){if(!state.branches.length)return emptyView('先发生一段对话。','完成聊天预演后，可以从某轮分叉，再比较不同表达。','导入聊天记录',0);let a=state.branches.find(b=>b.id===state.compareA)||state.branches[0];let b=state.branches.find(b=>b.id===state.compareB)||state.branches.find(x=>x.id!==a.id)||a;state.compareA=a.id;state.compareB=b.id;const same=a.id===b.id,compatible=!same&&a.persona.id===b.persona.id&&a.persona.version===b.persona.version&&JSON.stringify(a.context)===JSON.stringify(b.context),last=latestUser(b);return `<div class="compare-controls"><div class="field"><label for="compareA">左侧路径</label><select id="compareA">${branchOptions(a.id)}</select></div><span style="color:#9caa91;margin-top:22px">↔</span><div class="field"><label for="compareB">右侧路径</label><select id="compareB">${branchOptions(b.id)}</select></div><button class="button small" id="swapBranches">交换左右</button></div>${same?'<div class="hint-box" style="margin:0 0 20px">目前展示同一路径。请在聊天中点击“从这里分叉”，发送另一种表达后选择两条不同路径。</div>':`<div class="hint-box" style="margin:0 0 20px">${compatible?'✓ 同一人格版本与初始背景。可以观察两条路径的表达差异。':'两条路径的人格版本或背景不同；可并排查看，但不能把回应差异归因于措辞。'} 本页面为规则演示，不评价真实沟通效果。</div>`}<div class="compare-grid">${comparePanel(a)}${comparePanel(b)}</div><div class="review-grid"><section class="panel"><div class="panel-head"><h3>复盘检查清单</h3><span class="tag amber">需人工确认</span></div><div class="panel-body review-list"><div class="review-item">${icon('people')}<div><strong>人格是否像材料中的对象？</strong><p>回看来源证据。演示回复由固定规则生成，无法检验人格还原度。</p></div></div><div class="review-item">${icon('shield')}<div><strong>原意、事实与边界是否保留？</strong><p>${esc(b.context.boundary||'本次没有填写保护条件。')} 检查是否新增承诺或改变责任。</p></div></div><div class="review-item">${icon('arrow')}<div><strong>下一步是否更明确？</strong><p>观察请求与取舍是否具体，而不是只比较语气是否更柔和。</p></div></div></div></section><section class="panel"><div class="panel-head"><h3>再试一种说法</h3>${icon('edit')}</div><div class="panel-body"><label for="rewriteText" class="subtle">从右侧路径最近一条用户消息处分叉</label><textarea id="rewriteText" style="height:125px;margin-top:9px" ${!last?'disabled':''}>${esc(last?rewriteSuggestion(last.text):'先在这条路径发送一条消息。')}</textarea><p class="subtle">这是规则示例改写，请检查原意再预演。未实现 AI 评分或自动事实验证。</p></div><div class="panel-foot"><button class="button small" id="copyRewrite" ${!last?'disabled':''}>${icon('copy')}复制表达</button><button class="button primary" id="replayRewrite" ${!last?'disabled':''}>修改后再次预演 ${icon('arrow')}</button></div></section></div>`;}
function rewriteSuggestion(text){return /排不进|你们.*吧/.test(text)?'当前排期已满，这个需求暂时无法直接加入。若需要优先推进，请确认要调整哪个已排期需求，我们再据此评估安排。':text;}
function replayRewrite(){const b=state.branches.find(x=>x.id===state.compareB),last=latestUser(b),text=$('#rewriteText').value.trim();if(!last||!text)return notify('请填写准备重新预演的表达。');const index=b.messages.findIndex(m=>m.id===last.id);createBranch(b.persona,b.messages.slice(0,index),b.id,last.id,b.context);state.stage=2;state.draft=text;sendMessage();}
function render(){navigation();$('#view').innerHTML=[materialView,personaView,chatView,compareView][state.stage]();hydrateIcons();}
function updateMaterialMetrics(){const names=candidates();$('#materialLength').textContent=state.material.length;$('#recordCount').textContent=records(state.material).length;$('#personCount').textContent=names.length;$('#candidateList').innerHTML=candidateHTML(names);}
async function importFile(file){if(!file)return;if(file.size>2*1024*1024)return notify('文件超过 2 MB，请先选取相关片段。');if(!/\.(txt|md|json)$/i.test(file.name))return notify('请选择 TXT、MD 或 JSON 文件。');let text;try{text=await file.text();if(/\.json$/i.test(file.name)){const data=JSON.parse(text);const rows=Array.isArray(data)?data:Array.isArray(data.messages)?data.messages:null;if(rows){text=rows.map((r,i)=>{if(!r||typeof r!=='object')throw Error('invalid row');const speaker=r.speaker||r.sender||r.name||'未知对象';const content=r.text??r.content??r.message??'';return `[${r.time||i+1}] ${speaker}：${typeof content==='string'?content:JSON.stringify(content)}`;}).join('\n');}else text=JSON.stringify(data,null,2);}}catch{return notify('文件无法解析，请检查是否为有效的 UTF-8 文本或 JSON。');}state.material=text;state.materialName=file.name;state.materialVersion++;state.sample=false;state.context={background:'',goal:'',boundary:''};state.draft='';generatePersonas();}
async function saveWorkspace(){const button=$('#saveButton');button.disabled=true;try{const response=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({formatVersion:1,savedAt:new Date().toISOString(),state})});if(!response.ok)throw Error();const result=await response.json();notify(`已保存到 D 盘：${result.path}`);}catch{notify('保存需要本地预览服务。请通过本项目的启动脚本打开页面。');}finally{button.disabled=false;}}
async function restoreWorkspace(){try{const response=await fetch('/api/workspace');if(!response.ok)return;const data=await response.json();if(data&&data.formatVersion===1&&data.state&&Array.isArray(data.state.personas)&&Array.isArray(data.state.branches)&&typeof data.state.material==='string'){state=data.state;state.stage=Math.max(0,Math.min(3,Number(state.stage)||0));render();notify('已恢复上次主动保存的本地工作区。');}}catch{}}
document.addEventListener('click',event=>{const stage=event.target.closest('[data-stage]');if(stage)return setStage(Number(stage.dataset.stage));const person=event.target.closest('[data-persona]');if(person){state.selected=person.dataset.persona;return render();}const branch=event.target.closest('[data-branch]');if(branch){if(busy)return;state.activeBranch=branch.dataset.branch;state.draft='';return render();}const fork=event.target.closest('[data-fork]');if(fork)return forkMessage(fork.dataset.fork);const button=event.target.closest('button');if(!button)return;switch(button.id){case 'sampleButton':if(busy)return;state.material=SAMPLE;state.materialName='协作对话示例.txt';state.sample=true;state.materialVersion++;state.personas=[];state.selected=null;state.branches=[];state.activeBranch=null;state.compareA=null;state.compareB=null;state.context={background:'当前排期已满，新增需求需要明确取舍。',goal:'说明资源限制，并推动优先级协商',boundary:'不承诺额外产能，不编造交付日期。'};state.draft='这个需求我们排不进去，你们重评优先级吧。';state.stage=0;render();generatePersonas();break;case 'importButton':$('#fileInput').click();break;case 'generatePersonas':generatePersonas();break;case 'startPersona':startPersona();break;case 'sendMessage':sendMessage();break;case 'newSession':{const b=currentBranch();createBranch(b.persona,[],null,null,b.context);state.draft='';render();notify('已创建独立预演；发送前可以修改背景。');break;}case 'swapBranches':[state.compareA,state.compareB]=[state.compareB,state.compareA];render();break;case 'replayRewrite':replayRewrite();break;case 'copyRewrite':{const text=$('#rewriteText').value;navigator.clipboard.writeText(text).then(()=>notify('表达已复制。'),()=>{const field=$('#rewriteText');field.select();notify('剪贴板不可用，已选中文本，请手动复制。');});break;}case 'saveButton':saveWorkspace();break;case 'helpButton':$('#helpDialog').showModal();break;case 'closeHelp':$('#helpDialog').close();break;}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='materialText'){state.material=el.value;if(state.sample){state.sample=false;state.materialName='粘贴的对话材料';state.materialVersion++;$('#materialName').textContent=state.materialName;}updateMaterialMetrics();}if(el.dataset.context){const b=currentBranch();if(b&&!b.messages.length){b.context[el.dataset.context]=el.value;state.context[el.dataset.context]=el.value;}}if(el.id==='chatDraft')state.draft=el.value;});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='fileInput')importFile(el.files[0]);if(el.id==='chatPersona'){state.selected=el.value;startPersona();}if(el.id==='compareA'){state.compareA=el.value;render();}if(el.id==='compareB'){state.compareB=el.value;render();}});
document.addEventListener('keydown',event=>{if(event.target.id==='chatDraft'&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing&&event.keyCode!==229){event.preventDefault();sendMessage();}});
$('#helpDialog').addEventListener('click',event=>{if(event.target===$('#helpDialog'))$('#helpDialog').close();});
render();restoreWorkspace();
